"use client";

import {
  AnimatePresence,
  motion,
  useMotionValueEvent,
  useScroll,
  useTransform,
} from "motion/react";

import {
  CSSProperties,
  useRef,
  useState,
} from "react";

import {
  serviceCatalog,
  totalServices,
} from "@/data/serviceCatalog";

export function ServiceUniverse() {
  const sectionRef =
    useRef<HTMLElement>(null);

  const [activeIndex, setActiveIndex] =
    useState(0);

  const { scrollYProgress } =
    useScroll({
      target: sectionRef,
      offset: [
        "start start",
        "end end",
      ],
    });

  useMotionValueEvent(
    scrollYProgress,
    "change",
    (latest) => {
      const index = Math.min(
        serviceCatalog.length - 1,
        Math.floor(
          latest * serviceCatalog.length
        )
      );

      setActiveIndex(index);
    }
  );

  const active =
    serviceCatalog[activeIndex];

  const backgroundY = useTransform(
    scrollYProgress,
    [0, 1],
    ["0%", "-18%"]
  );

  const jumpTo = (index: number) => {
    const section =
      sectionRef.current;

    if (!section) return;

    const distance =
      section.offsetHeight -
      window.innerHeight;

    const position =
      section.offsetTop +
      (index /
        (serviceCatalog.length - 1)) *
        distance;

    window.scrollTo({
      top: position,
      behavior: "smooth",
    });
  };

  return (
    <section
      ref={sectionRef}
      id="service-universe"
      className="lawx-universe"
      style={
        {
          "--universe-accent":
            active.accent,
        } as CSSProperties
      }
    >
      <div className="lawx-universe-sticky">
        <motion.div
          className="lawx-universe-orb"
          style={{ y: backgroundY }}
        />

        <div className="lawx-universe-head">
          <span>
            01 / SERVICE UNIVERSE
          </span>

          <strong>
            {totalServices}
          </strong>
        </div>

        <div className="lawx-universe-layout">
          <div className="lawx-universe-nav">
            {serviceCatalog.map(
              (group, index) => (
                <button
                  type="button"
                  key={group.slug}
                  onClick={() =>
                    jumpTo(index)
                  }
                  className={
                    activeIndex === index
                      ? "active"
                      : ""
                  }
                >
                  <i
                    style={{
                      background:
                        group.accent,
                    }}
                  />

                  <span>
                    {String(
                      index + 1
                    ).padStart(2, "0")}
                  </span>

                  <strong>
                    {group.label}
                  </strong>

                  <b>
                    {
                      group.services
                        .length
                    }
                  </b>
                </button>
              )
            )}
          </div>

          <div className="lawx-universe-stage">
            <AnimatePresence mode="wait">
              <motion.div
                key={active.slug}
                className="lawx-universe-content"
                initial={{
                  opacity: 0,
                  y: 60,
                  scale: 0.96,
                }}
                animate={{
                  opacity: 1,
                  y: 0,
                  scale: 1,
                }}
                exit={{
                  opacity: 0,
                  y: -35,
                  scale: 0.97,
                }}
                transition={{
                  duration: 0.5,
                  ease: [
                    0.22,
                    1,
                    0.36,
                    1,
                  ],
                }}
              >
                <div className="lawx-category-meta">
                  <span>
                    {String(
                      activeIndex + 1
                    ).padStart(2, "0")}
                  </span>

                  <i />

                  <span>
                    {
                      active.services
                        .length
                    }{" "}
                    SERVICES
                  </span>
                </div>

                <h2>
                  {active.label}
                </h2>

                <div className="lawx-service-preview">
                  {active.services
                    .slice(0, 8)
                    .map(
                      (
                        service,
                        index
                      ) => (
                        <a
                          href="#"
                          key={service}
                        >
                          <span>
                            {String(
                              index + 1
                            ).padStart(
                              2,
                              "0"
                            )}
                          </span>

                          <strong>
                            {service}
                          </strong>

                          <b>↗</b>
                        </a>
                      )
                    )}
                </div>

                {active.services.length >
                  8 && (
                  <button
                    type="button"
                    className="lawx-open-all"
                    onClick={() =>
                      document
                        .querySelector(
                          ".lawx-search-services"
                        )
                        ?.dispatchEvent(
                          new MouseEvent(
                            "click",
                            {
                              bubbles:
                                true,
                            }
                          )
                        )
                    }
                  >
                    Explore all{" "}
                    {
                      active.services
                        .length
                    }{" "}
                    services
                    <span>↗</span>
                  </button>
                )}
              </motion.div>
            </AnimatePresence>
          </div>

          <div className="lawx-universe-number">
            <AnimatePresence mode="wait">
              <motion.span
                key={activeIndex}
                initial={{
                  opacity: 0,
                  y: 50,
                }}
                animate={{
                  opacity: 1,
                  y: 0,
                }}
                exit={{
                  opacity: 0,
                  y: -50,
                }}
                transition={{
                  duration: 0.35,
                }}
              >
                {String(
                  activeIndex + 1
                ).padStart(2, "0")}
              </motion.span>
            </AnimatePresence>
          </div>
        </div>

        <motion.div
          className="lawx-universe-progress"
          style={{
            scaleX: scrollYProgress,
          }}
        />
      </div>
    </section>
  );
}